'use strict';

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

function fetchAll(items, limit = DEFAULT_LIMIT) {
  return items.slice(0, limit).map((item) => item.id);
}

function total(values) {
  let sum = 0;
  for (const v of values) sum += v;
  return sum;
}

function average(values) {
  return total(values) / values.length;
}

module.exports = { fetchAll, total, average };

